IF OBJECT_ID(N'[dbo].[Tally]', N'U') IS NULL
BEGIN
    CREATE TABLE [dbo].[Tally]([n] [int] IDENTITY(1,1) NOT NULL, CONSTRAINT [PK_Tally] PRIMARY KEY CLUSTERED ([n] ASC) ON [PRIMARY]) ON [PRIMARY];
    SET IDENTITY_INSERT [dbo].[Tally] ON;
    WITH E1(N) AS (SELECT 1 UNION ALL SELECT 1 UNION ALL SELECT 1 UNION ALL SELECT 1 UNION ALL SELECT 1 UNION ALL SELECT 1 UNION ALL SELECT 1 UNION ALL SELECT 1 UNION ALL SELECT 1 UNION ALL SELECT 1),
         E2(N) AS (SELECT 1 FROM E1 a, E1 b),
         E4(N) AS (SELECT 1 FROM E2 a, E2 b)
    INSERT INTO [dbo].[Tally]([n]) SELECT TOP (10000) ROW_NUMBER() OVER (ORDER BY (SELECT NULL)) FROM E4;
    SET IDENTITY_INSERT [dbo].[Tally] OFF;
END
